// Photo asset "whiteboard" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/whiteboard.js"></script>
//   <img data-asset="whiteboard" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "whiteboard": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="whiteboard"]').forEach(function (img) { img.src = window.ASSETS["whiteboard"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
